let graphContext=null,graphCanvas=null;
const densityPoints=Array.from({length:260},(_,i)=>{const group=i%3,k=Math.floor(i/3),a=k*2.399963,gRadius=.11+Math.sqrt(k/90)*.38;const center=[[-.44,-.12],[.42,-.12],[.02,.48]][group];return {x:center[0]+Math.cos(a)*gRadius,y:center[1]+Math.sin(a)*gRadius*.65,z:Math.sin(i*1.91)*.5,group}});
const graphColors=['#a5cdbb','#9bb8d9','#d1b08a'];
function project(p,w,h){const angle=state.graphAngle,rotX=p.x*Math.cos(angle)+p.z*Math.sin(angle),depth=p.z*Math.cos(angle)-p.x*Math.sin(angle),persp=1+depth*.12;return {x:w*.5+rotX*w*.37*state.graphZoom*persp,y:h*.51+p.y*h*.4*state.graphZoom*persp,depth}}
function filteredObjects(){return work().objects.filter(o=>(state.galaxyFilter==='全部'||o.type===state.galaxyFilter||(state.galaxyFilter==='人物'&&o.type==='组织'))&&(!state.galaxyQuery||(o.name+' '+o.summary).toLowerCase().includes(state.galaxyQuery.toLowerCase())))}
function setupGalaxy(){graphCanvas=$('#galaxy-canvas');if(!graphCanvas)return;try{graphContext=graphCanvas.getContext('2d')}catch{graphContext=null}if(!graphContext){state.galaxyList=true;$('#graph-hint').textContent='绘图不可用，已切换完整对象列表。来源与正文仍可打开。'}let drag=null,moved=false;
 graphCanvas.addEventListener('pointerdown',e=>{drag={x:e.clientX,angle:state.graphAngle};moved=false;graphCanvas.setPointerCapture(e.pointerId)});
 graphCanvas.addEventListener('pointermove',e=>{if(drag){moved=moved||Math.abs(e.clientX-drag.x)>4;state.graphAngle=drag.angle+(e.clientX-drag.x)*.004;drawGalaxy()}});
 graphCanvas.addEventListener('pointerup',()=>{drag=null;if(moved)graphCanvas.style.cursor='grab'});
 graphCanvas.addEventListener('pointercancel',()=>{drag=null});
 graphCanvas.addEventListener('wheel',e=>{e.preventDefault();state.graphZoom=Math.min(1.45,Math.max(.65,state.graphZoom-e.deltaY*.001));drawGalaxy()},{passive:false});
 requestAnimationFrame(drawGalaxy);
}
function drawGalaxy(){if(state.page!=='galaxy'||!$('#sky-labels'))return;const filtered=filteredObjects(),list=$('#sky-list'),labels=$('#sky-labels');const showList=state.galaxyList||!graphContext;list.hidden=!showList;graphCanvas.hidden=showList;labels.hidden=showList;$$('.cluster-label').forEach(e=>e.hidden=showList||state.galaxyFilter!=='全部'||!!state.galaxyQuery);$$('[data-action="galaxy-mode"]').forEach(e=>e.classList.toggle('active',(e.dataset.mode==='list')===showList));if(showList){list.innerHTML=filtered.length?filtered.map(o=>`<button data-action="select-star" data-id="${o.id}"><i class="tone-dot" style="background:${graphColors[o.group%3]}"></i><span>${esc(o.name)}</span><small>${esc(o.type)}</small>${icon('chevron')}</button>`).join(''):'<div class="empty" style="min-height:240px"><h2>这一片星空，暂时没有结果。</h2><p>试试其他关键词或清除类型筛选。</p></div>';return}
 const rect=$('#sky').getBoundingClientRect(),w=rect.width,h=rect.height,dpr=Math.min(devicePixelRatio||1,2),ctx=graphContext;if(!w||!h)return;graphCanvas.width=Math.round(w*dpr);graphCanvas.height=Math.round(h*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);ctx.fillStyle='#09121c';ctx.fillRect(0,0,w,h);
 const mist=ctx.createRadialGradient(w*.5,h*.51,0,w*.5,h*.51,w*.6);mist.addColorStop(0,'#1c33403a');mist.addColorStop(.55,'#172b3433');mist.addColorStop(1,'#0a121c00');ctx.fillStyle=mist;ctx.fillRect(0,0,w,h);
 for(let i=0;i<240;i++){const x=((Math.sin(i*46.27)*42617)%1+1)%1*w,y=((Math.cos(i*31.93)*19447)%1+1)%1*h;ctx.fillStyle=i%9===0?'#a3b5bf70':'#8599ab30';ctx.beginPath();ctx.arc(x,y,i%9===0?1:.55,0,Math.PI*2);ctx.fill()}
 const pts=densityPoints.map(p=>({...project(p,w,h),group:p.group}));const dim=state.galaxyFilter!=='全部'||!!state.galaxyQuery;
 ctx.lineWidth=.6;for(let i=0;i<pts.length;i++){const a=pts[i];for(let step of [3,6,15]){const j=(i+step)%pts.length,b=pts[j];if(a.group!==b.group)continue;if(Math.hypot(a.x-b.x,a.y-b.y)>w*.3)continue;ctx.strokeStyle=graphColors[a.group]+(dim?'0b':'20');ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke()}}
 pts.forEach((p,i)=>{ctx.fillStyle=graphColors[p.group]+(dim?'35':i%5===0?'aa':'65');ctx.beginPath();ctx.arc(p.x,p.y,i%5===0?1.7:.85,0,Math.PI*2);ctx.fill()});
 const all=work().objects.map(o=>({...o,...project(o,w,h)}));const selected=all.find(o=>o.id===state.galaxySelected);ctx.lineWidth=.8;all.forEach(o=>(o.relations||[]).forEach(id=>{const dest=all.find(x=>x.id===id);if(!dest)return;const strong=o.id===state.galaxySelected||id===state.galaxySelected;ctx.strokeStyle=strong?'#c6b28688':'#93b6c235';ctx.beginPath();ctx.moveTo(o.x,o.y);ctx.lineTo(dest.x,dest.y);ctx.stroke()}));
 const focusedIds=new Set([state.galaxySelected,...(object(state.galaxySelected)?.relations||[])]);const visible=w<500&&!state.galaxyQuery&&state.galaxyFilter==='全部'?filtered.filter(o=>focusedIds.has(o.id)).slice(0,6):filtered;$('#graph-hint').innerHTML=w<500?'当前聚焦 '+visible.length+' 个标签 · 全部对象可在列表查看<br>拖动旋转；背景连接仅为密度演示。':'拖动旋转 · 滚轮缩放 · 仅标记对象可选<br>背景连接为密度演示，不代表记忆质量。';const boxes=[];labels.innerHTML=visible.map(o=>{const p=all.find(x=>x.id===o.id);let x=Math.max(65,Math.min(w-65,p.x)),y=Math.max(145,Math.min(h-115,p.y));const wid=Math.min(140,o.name.length*12+26);const origin={x,y};const fits=(tx,ty)=>!boxes.some(b=>Math.abs(tx-b.x)<(wid+b.w)/2+5&&Math.abs(ty-b.y)<38);if(!fits(x,y)){let found=false;for(let radius=1;radius<8&&!found;radius++){for(const dx of [0,1,-1]){for(const dy of [1,-1]){const tx=Math.max(wid/2+12,Math.min(w-wid/2-12,origin.x+dx*radius*45));const ty=Math.max(148,Math.min(h-128,origin.y+dy*radius*40));if(fits(tx,ty)){x=tx;y=ty;found=true;break}}if(found)break}}}boxes.push({x,y,w:wid});if(Math.hypot(x-p.x,y-p.y)>24){ctx.strokeStyle=graphColors[o.group%3]+'55';ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(x,y);ctx.stroke()}ctx.fillStyle=graphColors[o.group%3];ctx.beginPath();ctx.arc(p.x,p.y,3,0,Math.PI*2);ctx.fill();if(o.id===state.galaxySelected){ctx.strokeStyle='#d8bd9170';ctx.lineWidth=1;ctx.beginPath();ctx.arc(p.x,p.y,17,0,Math.PI*2);ctx.stroke()}
 return `<button class="star-label ${o.id===state.galaxySelected?'selected':''}" style="left:${x}px;top:${y}px" data-action="select-star" data-id="${o.id}" aria-label="${esc(o.type+'：'+o.name)}">${esc(o.name)}</button>`}).join('');
 if(!filtered.length)labels.innerHTML='<div class="empty" style="position:absolute;inset:130px 20px 110px;pointer-events:none"><h2>没有匹配的对象</h2><p>更换关键词或类型筛选。</p></div>';
}
